import React, { useEffect, useMemo, useState } from 'react';
import { Table, Input, Button, Space, Tag, DatePicker, Select, message, Popconfirm, Drawer, Descriptions, Badge, Modal, Spin, Typography } from 'antd';
import type { ColumnsType } from 'antd/es/table';
import dayjs, { Dayjs } from 'dayjs';
import { buildAuthHeaders } from '../api';

const { Text } = Typography;

type QuantRow = {
  id: string;
  created_at: string;
  thought_form: string;
  energy_weight: number;
  composite_emotion?: any;
  tags?: string[] | any;
  source?: string | null;
  payload?: any;
  goals_count?: number;
};

type GoalRow = {
  id: string;
  quant_id: string;
  priority: number;
  is_active?: boolean;
  status?: string;
  title?: string;
  description?: string;
  created_at?: string;
};

const { RangePicker } = DatePicker;

export default function SoulQuants() {
  const [items, setItems] = useState<QuantRow[]>([]);
  const [total, setTotal] = useState(0);
  const [totalAll, setTotalAll] = useState<number | null>(null);
  const [total24h, setTotal24h] = useState<number | null>(null);
  const [loading, setLoading] = useState(false);
  const [q, setQ] = useState('');
  const [source, setSource] = useState<string | undefined>();
  const [dateRange, setDateRange] = useState<[Dayjs | null, Dayjs | null] | null>(null);
  const [selectedRowKeys, setSelectedRowKeys] = useState<React.Key[]>([]);
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState(50);
  const [detailOpen, setDetailOpen] = useState(false);
  const [detailItem, setDetailItem] = useState<QuantRow | null>(null);
  const [goals, setGoals] = useState<GoalRow[]>([]);
  const [goalsLoading, setGoalsLoading] = useState(false);
  const [loadingIssues, setLoadingIssues] = useState(false);
  const [neighbors, setNeighbors] = useState<any[]>([]);
  const [neighborsLoading, setNeighborsLoading] = useState(false);

  const fetchCounters = async () => {
    try {
      const commonOpts: RequestInit = { headers: buildAuthHeaders() };
      // Всего
      const resAll = await fetch(`/api/admin/soul/quants/search?limit=1&offset=0`, commonOpts);
      const dataAll = await resAll.json();
      if (resAll.ok) setTotalAll(Number(dataAll.total || 0));
      // За 24 часа
      const since = dayjs().subtract(24, 'hour').format('YYYY-MM-DD HH:mm:ss');
      const res24 = await fetch(`/api/admin/soul/quants/search?limit=1&offset=0&date_from=${encodeURIComponent(since)}`, commonOpts);
      const data24 = await res24.json();
      if (res24.ok) setTotal24h(Number(data24.total || 0));
    } catch (e) {
      // не блокируем UI
    }
  };

  const fetchData = async () => {
    try {
      setLoading(true);
      const params = new URLSearchParams();
      if (q) params.append('q', q);
      if (source) params.append('source', source);
      if (dateRange && dateRange[0]) params.append('date_from', dateRange[0]!.format('YYYY-MM-DD HH:mm:ss'));
      if (dateRange && dateRange[1]) params.append('date_to', dateRange[1]!.format('YYYY-MM-DD HH:mm:ss'));
      params.append('limit', String(pageSize));
      params.append('offset', String((page - 1) * pageSize));
      params.append('sort_by', 'created_at');
      params.append('sort_dir', 'desc');

      const res = await fetch(`/api/admin/soul/quants/search?${params.toString()}` , { headers: buildAuthHeaders() });
      const data = await res.json();
      if (!res.ok) throw new Error(data?.detail || 'fetch failed');
      setItems(data.items || []);
      setTotal(data.total || 0);
    } catch (e: any) {
      message.error(`Ошибка загрузки: ${e.message || e}`);
    } finally {
      setLoading(false);
      // Обновляем счётчики на фоне
      fetchCounters();
    }
  };

  useEffect(() => {
    fetchCounters();
  }, []);

  useEffect(() => {
    fetchData();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [q, source, dateRange, page, pageSize]);

  const onBulkDelete = async () => {
    if (selectedRowKeys.length === 0) return;
    try {
      setLoading(true);
      const res = await fetch('/api/admin/soul/quants/bulk_delete', {
        method: 'POST',
        headers: { ...buildAuthHeaders(), 'Content-Type': 'application/json' },
        body: JSON.stringify({ ids: selectedRowKeys }),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data?.detail || 'bulk delete failed');
      message.success(`Удалено: ${data.deleted}`);
      setSelectedRowKeys([]);
      fetchData();
    } catch (e: any) {
      message.error(`Ошибка удаления: ${e.message || e}`);
    } finally {
      setLoading(false);
    }
  };

  const loadGoals = async (quantId: string) => {
    try {
      setGoalsLoading(true);
      const res = await fetch(`/api/admin/soul/goals/by-quant?quant_id=${encodeURIComponent(quantId)}`, {
        headers: buildAuthHeaders(),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data?.detail || 'failed');
      setGoals(data.items || []);
    } catch (e:any) {
      message.error(`Ошибка загрузки целей: ${e.message || e}`);
      setGoals([]);
    } finally {
      setGoalsLoading(false);
    }
  };

  const loadNeighbors = async (quantId: string) => {
    try {
      setNeighborsLoading(true);
      const resp = await fetch(`/api/admin/soul/graph/top_neighbors?quant_id=${encodeURIComponent(quantId)}&limit=50`, { headers: buildAuthHeaders() });
      const data = await resp.json();
      setNeighbors(Array.isArray(data.items) ? data.items : []);
    } catch {
      setNeighbors([]);
    } finally {
      setNeighborsLoading(false);
    }
  };

  const handleDeleteQuant = async (quantId: string) => {
    try {
      const ok = await new Promise<boolean>((resolve) => {
        Modal.confirm({
          title: 'Удалить квант?',
          content: 'Квант будет удалён. Связанные цели и связи также будут безопасно удалены.',
          okText: 'Удалить', cancelText: 'Отмена',
          onOk: () => resolve(true), onCancel: () => resolve(false),
        });
      });
      if (!ok) return;
      const res = await fetch(`/api/admin/soul/quant/${encodeURIComponent(quantId)}`, {
        method: 'DELETE',
        headers: buildAuthHeaders(),
      });
      const data = await res.json().catch(() => ({}));
      if (!res.ok) throw new Error(data?.detail || 'delete failed');
      message.success('Квант удалён');
      setDetailOpen(false);
      setDetailItem(null);
      fetchData();
    } catch (e:any) {
      message.error(`Ошибка удаления кванта: ${e.message || e}`);
    }
  };

  const handleDeleteGoal = async (goalId: string) => {
    try {
      // Разрыв связи (не удаление кванта, безопасно удаляет запись цели)
      const res = await fetch('/api/admin/soul/goals/actions/unlink', {
        method: 'POST',
        headers: { ...buildAuthHeaders(), 'Content-Type': 'application/json' },
        body: JSON.stringify({ goal_id: goalId }),
      });
      const data = await res.json().catch(() => ({}));
      if (!res.ok) throw new Error(data?.detail || 'unlink failed');
      message.success('Связь цели разорвана');
      if (detailItem) loadGoals(detailItem.id);
      fetchData();
    } catch (e:any) {
      message.error(`Ошибка разрыва связи: ${e.message || e}`);
    }
  };

  const handleReassignGoal = async (goalId: string, currentQuantId: string) => {
    try {
      const targetId = window.prompt('Введите ID базового кванта для переназначения цели:', currentQuantId);
      if (!targetId) return;
      const res = await fetch('/api/admin/soul/goals/reassign', {
        method: 'POST',
        headers: { ...buildAuthHeaders(), 'Content-Type': 'application/json' },
        body: JSON.stringify({ goal_id: goalId, target_quant_id: targetId.trim() }),
      });
      const data = await res.json().catch(() => ({}));
      if (!res.ok) throw new Error(data?.detail || 'reassign failed');
      message.success('Цель переназначена');
      if (detailItem) loadGoals(detailItem.id);
      fetchData();
    } catch (e:any) {
      message.error(`Ошибка переназначения цели: ${e.message || e}`);
    }
  };

  const unlinkEdge = async (fromId: string, toId: string) => {
    try {
      const reason = window.prompt('Причина разрыва связи:', '') || '';
      const res = await fetch('/api/admin/soul/graph/unlink_edge', {
        method: 'POST',
        headers: { ...buildAuthHeaders(), 'Content-Type': 'application/json' },
        body: JSON.stringify({ from_quant_id: fromId, to_quant_id: toId, bidirectional: true, reason })
      });
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      message.success('Связь разорвана');
      if (detailItem) loadNeighbors(detailItem.id);
    } catch (e:any) {
      message.error('Не удалось разорвать связь');
    }
  };

  const loadEncodingIssues = async () => {
    try {
      setLoading(true);
      setLoadingIssues(true);
      const res = await fetch('/api/admin/soul/encoding/issues?limit=50', { headers: buildAuthHeaders() });
      const data = await res.json();
      if (!res.ok) throw new Error(data?.detail || 'issues fetch failed');
      setItems(data.items || []);
      setTotal(data.total || 0);
      setPage(1);
      setPageSize(50);
      message.success(`Найдено проблем: ${data.items?.length || 0}`);
    } catch (e:any) {
      message.error(`Ошибка выборки проблем: ${e.message || e}`);
    } finally {
      setLoading(false);
      setLoadingIssues(false);
    }
  };

  const fixSelectedEncoding = async () => {
    if (selectedRowKeys.length === 0) {
      message.info('Не выбраны строки для фикса.');
      return;
    }
    try {
      const ok = await new Promise<boolean>((resolve) => {
        Modal.confirm({ title: 'Исправить кодировку?', content: `Будет исправлено записей: ${selectedRowKeys.length}`, okText: 'Исправить', cancelText: 'Отмена', onOk: () => resolve(true), onCancel: () => resolve(false) });
      });
      if (!ok) return;
      setLoading(true);
      const res = await fetch('/api/admin/soul/encoding/fix', {
        method: 'POST',
        headers: { ...buildAuthHeaders(), 'Content-Type': 'application/json' },
        body: JSON.stringify({ ids: selectedRowKeys }),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data?.detail || 'fix failed');
      message.success(`Исправлено: ${data.fixed}`);
      setSelectedRowKeys([]);
      // Перезагружаем текущую выборку
      fetchData();
    } catch (e:any) {
      message.error(`Ошибка фикса: ${e.message || e}`);
    } finally {
      setLoading(false);
    }
  };

  const columns: ColumnsType<QuantRow> = useMemo(() => [
    {
      title: 'Время',
      dataIndex: 'created_at',
      width: 170,
      sorter: false,
    },
    {
      title: 'Квант',
      dataIndex: 'thought_form',
      ellipsis: true,
      render: (t: string) => <span title={t}>{t}</span>,
    },
    {
      title: 'Ew',
      dataIndex: 'energy_weight',
      width: 80,
      render: (v: number) => (v != null ? v.toFixed(2) : ''),
    },
    {
      title: 'Теги',
      dataIndex: 'tags',
      width: 220,
      render: (v: any) => {
        const arr: string[] = Array.isArray(v) ? v : [];
        return <Space wrap>{arr.slice(0, 6).map((t) => <Tag key={t}>{t}</Tag>)}</Space>;
      },
    },
    {
      title: 'Цели',
      dataIndex: 'goals_count',
      width: 90,
      render: (n?: number) => (n && n > 0 ? <Badge count={n} style={{ backgroundColor: '#722ed1' }} /> : 0),
    },
    {
      title: 'Источник',
      dataIndex: 'source',
      width: 140,
    },
  ], []);

  return (
    <div style={{ padding: 16 }}>
      <Space wrap style={{ marginBottom: 12, width: '100%', justifyContent: 'space-between' }}>
        <Space wrap>
          <Input.Search
            allowClear
            placeholder="Поиск по тексту/тегам/payload"
            onSearch={(v) => { setPage(1); setQ(v.trim()); }}
            style={{ width: 360 }}
          />
          <Input
            allowClear
            placeholder="source = K0.md"
            value={source}
            onChange={(e) => { setPage(1); setSource(e.target.value || undefined); }}
            style={{ width: 220 }}
          />
          <RangePicker
            showTime
            value={dateRange as any}
            onChange={(v) => { setPage(1); setDateRange(v as any); }}
          />
          <Button onClick={loadEncodingIssues} loading={loadingIssues}>Найти проблемы кодировки (50)</Button>
          <Button onClick={fixSelectedEncoding} disabled={selectedRowKeys.length === 0}>Исправить выбранные</Button>
        </Space>
        <Space wrap>
          <div style={{ fontSize: 12, color: 'var(--text-secondary)' }}>
            Всего: <b>{totalAll != null ? totalAll : '—'}</b> · За 24ч: <b>{total24h != null ? total24h : '—'}</b>
          </div>
          <Popconfirm
            title="Удалить выбранные кванты?"
            okText="Да"
            cancelText="Нет"
            onConfirm={onBulkDelete}
            disabled={selectedRowKeys.length === 0}
          >
            <Button danger disabled={selectedRowKeys.length === 0}>Удалить выбранные</Button>
          </Popconfirm>
          <Button onClick={() => { fetchData(); }}>Обновить</Button>
        </Space>
      </Space>

      <Table
        rowKey="id"
        loading={loading}
        dataSource={items}
        columns={columns}
        pagination={{
          current: page,
          pageSize,
          total,
          onChange: (p, ps) => { setPage(p); setPageSize(ps); },
          showSizeChanger: true,
          pageSizeOptions: [20, 50, 100, 200],
        }}
        rowSelection={{
          selectedRowKeys,
          onChange: setSelectedRowKeys,
          preserveSelectedRowKeys: true,
        }}
        onRow={(record) => ({
          onClick: () => {
            setDetailItem(record);
            setDetailOpen(true);
            loadGoals(record.id);
            loadNeighbors(record.id);
          }
        })}
      />

      <Drawer
        title="Детали кванта"
        placement="right"
        width={640}
        destroyOnClose
        onClose={() => setDetailOpen(false)}
        open={detailOpen}
      >
        {detailItem && (
          <>
            <Descriptions column={1} size="small" bordered>
              <Descriptions.Item label="ID">{detailItem.id}</Descriptions.Item>
              <Descriptions.Item label="Время">{detailItem.created_at}</Descriptions.Item>
              <Descriptions.Item label="Ew">{detailItem.energy_weight}</Descriptions.Item>
              <Descriptions.Item label="Источник">{detailItem.source || ''}</Descriptions.Item>
              <Descriptions.Item label="Эмоция">{detailItem.composite_emotion ? JSON.stringify(detailItem.composite_emotion) : ''}</Descriptions.Item>
              <Descriptions.Item label="Теги">{Array.isArray(detailItem.tags) ? detailItem.tags.join(', ') : ''}</Descriptions.Item>
              <Descriptions.Item label="Целей">{detailItem.goals_count ?? 0}</Descriptions.Item>
            </Descriptions>

            <div style={{ marginTop: 12 }}>
              <div style={{ fontWeight: 600, marginBottom: 4 }}>Квант (thought_form)</div>
              <div style={{ whiteSpace: 'pre-wrap', background: 'var(--bg-card)', padding: 8, borderRadius: 6 }}>{detailItem.thought_form}</div>
            </div>

            <div style={{ marginTop: 12, display: 'flex', gap: 8 }}>
              <Button danger onClick={() => handleDeleteQuant(detailItem.id)}>Удалить квант</Button>
              <Button onClick={() => loadGoals(detailItem.id)} loading={goalsLoading}>Обновить цели</Button>
            </div>

            <div style={{ marginTop: 16 }}>
              <div style={{ fontWeight: 600, marginBottom: 8 }}>Цели, связанные с квантом</div>
              {goalsLoading ? (
                <div>Загрузка целей…</div>
              ) : goals.length === 0 ? (
                <div>Целей нет</div>
              ) : (
                <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
                  {goals.map(g => (
                    <div key={g.id} style={{ border: '1px solid var(--border-color)', borderRadius: 6, padding: 8 }}>
                      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                        <div>
                          <div><b>{g.title || '(без названия)'}</b></div>
                          <div style={{ fontSize: 12, color: 'var(--text-secondary)' }}>ID: {g.id} · приоритет: {g.priority?.toFixed?.(2) || g.priority}</div>
                          {g.description && <div style={{ fontSize: 12, marginTop: 4 }}>{g.description}</div>}
                        </div>
                        <Space>
                          <Button size="small" danger onClick={() => handleDeleteGoal(g.id)}>Разорвать связь</Button>
                          <Button size="small" onClick={() => handleReassignGoal(g.id, detailItem.id)}>Переназначить</Button>
                        </Space>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>

            <div style={{ marginTop: 16 }}>
              <div style={{ fontWeight: 600, marginBottom: 8 }}>Соседи по связям</div>
              <div style={{ border: '1px solid var(--border-color)', borderRadius: 6, padding: 8, maxHeight: 220, overflow: 'auto' }}>
                {neighborsLoading ? (
                  <Spin />
                ) : neighbors.length === 0 ? (
                  <Text type="secondary">Соседи не найдены</Text>
                ) : (
                  <Space direction="vertical" style={{ width: '100%' }} size={8}>
                    {neighbors.map((n: any) => (
                      <div key={n.neighbor_id} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                        <div>
                          <div><Text strong>ID:</Text> {n.neighbor_id}</div>
                          <div style={{ fontSize: 12, color: 'var(--text-secondary)' }}>strength: {(n.strength || 0).toFixed(3)} · overlap: {(n.keyword_overlap || 0).toFixed(3)}</div>
                        </div>
                        <Button size="small" danger onClick={() => unlinkEdge(detailItem.id, n.neighbor_id)}>Разорвать</Button>
                      </div>
                    ))}
                  </Space>
                )}
              </div>
            </div>
          </>
        )}
      </Drawer>
    </div>
  );
}


